class Node {
    constructor(data, next = null) {
        this.next = next;
        this.data = data;
    }

    toString() {
        return String(this.data);
    }
}

class LinkedList {
    constructor(head = null) {
        this.head = head;
    }

    length() {
        let curr = this.head;
        let counter = 0;
        while (curr !== null) {
            counter += 1;
            curr = curr.next;
        }
        return counter;
    }

    insertToFront(data) {
        if (data === null || data === undefined) return null;
        const node = new Node(data, this.head);
        this.head = node;
        return node;
    }

    append(data) {
        if (data === null || data === undefined) return null;
        const node = new Node(data);
        if (this.head === null) {
            this.head = node;
            return node;
        }
        let curr = this.head;
        while (curr.next !== null) curr = curr.next;
        curr.next = node;
        return node;
    }

    find(data) {
        if (data === null || data === undefined) return null;
        let curr = this.head;
        while (curr !== null) {
            if (curr.data === data) return curr;
            curr = curr.next;
        }
        return null;
    }

    delete(data) {
        if (data === null || data === undefined) return;
        if (this.head === null) return;
        if (this.head.data === data) {
            this.head = this.head.next;
            return;
        }
        let prev = this.head;
        let curr = this.head.next;
        while (curr !== null) {
            if (curr.data === data) {
                prev.next = curr.next;
                return;
            }
            prev = curr;
            curr = curr.next;
        }
    }

    printList() {
        let curr = this.head;
        while (curr !== null) {
            console.log(curr.data);
            curr = curr.next;
        }
    }

    getAllData() {
        const data = [];
        let curr = this.head;
        while (curr !== null) {
            data.push(curr.data);
            curr = curr.next;
        }
        return data;
    }
}

